__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"POLICY_DATE",{enumerable:!0,get:function(){return o}}),e.privacyPolicy=function(s,t){const n=t.developer||('es'===s?'[tu nombre o tu empresa]':'[your name or company]'),l=t.email||('es'===s?'[tu correo de contacto]':'[your contact email]');if('en'===s)return{title:t.app+' privacy policy',updated:'Last updated: '+o.en,sections:[{title:'Who we are',paragraphs:[n+' develops '+t.app+' ("the app"). For any question about your data, write to '+l+'.']},{title:'Data kept on your phone',paragraphs:['Your progress (level, records, the last 60 days of history), your settings and your lives are stored only on your device. We have no servers or user accounts, so we never receive them.']},{title:'Advertising (Google AdMob)',paragraphs:['The app shows ads from Google AdMob. To show and measure them, Google may collect your device advertising ID, your IP address, technical data about your phone and how you interact with ads.','In the European Economic Area and the United Kingdom we ask for your consent with Google\'s form before personalised ads are shown; you can change it in Settings \u203a Ad privacy choices. On iPhone, the system asks whether you allow tracking (App Tracking Transparency).','More information: https://policies.google.com/technologies/ads']},{title:'Anonymous statistics (only if you agree)',paragraphs:['If you allow it, the app sends usage data to PostHog (servers in the European Union): which modes you play, scores, game length, language, device type and technical errors, together with a random identifier created on your phone. It never includes your name, email or advertising identifiers. You can turn it off any time in Settings.']},{title:'Notifications',paragraphs:['The daily reminder is a local notification scheduled on your phone; no data is sent to anyone. You can turn it off in Settings.']},{title:'Purchases',paragraphs:['The "Remove ads" purchase is processed by Google Play or the App Store under their own terms. We never receive your payment details: the app only receives the store\'s confirmation that the purchase exists, so it can remove the ads and restore it if you reinstall.']},{title:'Why and on what basis',paragraphs:['To run the game (your request to use it), to show ads (your consent, or Google\'s legitimate interest for non-personalised ads) and to improve the app with statistics (your consent).']},{title:'How long',paragraphs:['Data on your phone stays until you uninstall the app. Anonymous statistics are kept for at most 12 months.']},{title:'Children',paragraphs:['The app is not directed at children under 13.']},{title:'Your rights',paragraphs:['You can ask for access, correction, deletion, restriction, objection and portability by writing to '+l+'. Uninstalling the app deletes everything stored on your phone. You may also complain to your data protection authority.']},{title:'Changes',paragraphs:['If this policy changes, we will publish the new version here with its date.']}]};return{title:'Pol\xedtica de privacidad de '+t.app,updated:'\xdaltima actualizaci\xf3n: '+o.es,sections:[{title:'Qui\xe9nes somos',paragraphs:[n+' desarrolla '+t.app+' (\xabla app\xbb). Para cualquier duda sobre tus datos, escribe a '+l+'.']},{title:'Datos que se guardan en tu m\xf3vil',paragraphs:['Tu progreso (nivel, r\xe9cords, historial de los \xfaltimos 60 d\xedas), tus ajustes y tus vidas se guardan solo en tu dispositivo. No tenemos servidores ni cuentas de usuario, as\xed que nunca los recibimos.']},{title:'Publicidad (Google AdMob)',paragraphs:['La app muestra anuncios de Google AdMob. Para mostrarlos y medirlos, Google puede recoger el identificador de publicidad del dispositivo, tu direcci\xf3n IP, datos t\xe9cnicos del m\xf3vil y c\xf3mo interact\xfaas con los anuncios.','En el Espacio Econ\xf3mico Europeo y el Reino Unido te pedimos el consentimiento con el formulario de Google antes de mostrar anuncios personalizados; puedes cambiarlo en Ajustes \u203a Privacidad de los anuncios. En iPhone, el sistema te pregunta si permites el rastreo (App Tracking Transparency).','M\xe1s informaci\xf3n: https://policies.google.com/technologies/ads']},{title:'Estad\xedsticas an\xf3nimas (solo si aceptas)',paragraphs:['Si lo permites, la app env\xeda a PostHog (servidores en la Uni\xf3n Europea) datos de uso: qu\xe9 modos juegas, puntuaciones, duraci\xf3n de las partidas, idioma, tipo de dispositivo y errores t\xe9cnicos, junto con un identificador aleatorio creado en tu m\xf3vil. Nunca incluye tu nombre, tu correo ni identificadores publicitarios. Puedes desactivarlo cuando quieras en Ajustes.']},{title:'Notificaciones',paragraphs:['El recordatorio diario es una notificaci\xf3n local programada en tu m\xf3vil: no se env\xeda ning\xfan dato a nadie. Puedes desactivarlo en Ajustes.']},{title:'Compras',paragraphs:['La compra \xabQuitar anuncios\xbb la gestionan Google Play o la App Store seg\xfan sus propias condiciones. Nunca recibimos tus datos de pago: la app solo recibe de la tienda la confirmaci\xf3n de que la compra existe, para quitar los anuncios y restaurarla si reinstalas.']},{title:'Para qu\xe9 y con qu\xe9 base',paragraphs:['Para que el juego funcione (porque quieres usarlo), para mostrar anuncios (tu consentimiento o, en los anuncios no personalizados, el inter\xe9s leg\xedtimo de Google) y para mejorar la app con estad\xedsticas (tu consentimiento).']},{title:'Cu\xe1nto tiempo',paragraphs:['Los datos del m\xf3vil se guardan hasta que desinstalas la app. Las estad\xedsticas an\xf3nimas se conservan como m\xe1ximo 12 meses.']},{title:'Menores',paragraphs:['La app no est\xe1 dirigida a menores de 13 a\xf1os.']},{title:'Tus derechos',paragraphs:['Puedes pedir el acceso, la rectificaci\xf3n, la supresi\xf3n, la limitaci\xf3n, la oposici\xf3n y la portabilidad escribiendo a '+l+'. Al desinstalar la app se borra todo lo guardado en tu m\xf3vil. Tambi\xe9n puedes reclamar ante la Agencia Espa\xf1ola de Protecci\xf3n de Datos (www.aepd.es).']},{title:'Cambios',paragraphs:['Si esta pol\xedtica cambia, publicaremos aqu\xed la nueva versi\xf3n con su fecha.']}]}};const o={es:'27 de octubre de 2026',en:'October 27, 2026'}},841,[]);